// Helper to count words (split by whitespace)
function countWords(str) {
  return str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean).length;
}

for (const post of articles) {
  const filePath = path.join(postsDir, `${post.slug}.json`);
  
  let totalWords = 0;
  totalWords += countWords(post.quickAnswer.text);
  for (const h of post.quickAnswer.highlights) totalWords += countWords(h);
  for (const s of post.sections) {
    totalWords += countWords(s.title);
    totalWords += countWords(s.content);
  }
  for (const f of post.faq) {
    totalWords += countWords(f.question);
    totalWords += countWords(f.answer);
  }

  console.log(`[${post.slug}] Total Words: ${totalWords}`);
  if (totalWords < 1500) {
    console.warn(`⚠️ Warning: ${post.slug} has ${totalWords} words (< 1500 words target!)`);
  } else if (totalWords > 2200) {
    console.warn(`⚠️ Warning: ${post.slug} has ${totalWords} words (> 2200 words target!)`);
  } else {
    console.log(`✅ Word count in perfect range (1500 - 2200 words).`);
  }

  fs.writeFileSync(filePath, JSON.stringify(post, null, 2), 'utf-8');
  console.log(`Saved: ${filePath}`);
}

console.log('\nAll 5 articles created successfully!');
